static z_t1802_t z_t1796_call(z_t1796_t* _it);
static z_t1802_t z_t1796_call(z_t1796_t* _it) {
    z_t1802_t _out = {0};
    while (_it->idx < _it->m->entries_len) {
        if (_it->m->entries[_it->idx].alive) {
            _out.tag = Z_OPTIONVIEW_MAPENTRY_STRING_STRING_TAG_SOME;
            _out.data = &_it->m->entries[_it->idx];
            _it->idx++;
            return _out;
        }
        _it->idx++;
    }
    _out.tag = Z_OPTIONVIEW_MAPENTRY_STRING_STRING_TAG_NONE;
    return _out;
}

