static void z_t1275_destroy(z_t1275_t* u) {
    if (!u) return;
    if (!u->data) return;
    switch (u->tag) {
        case Z_OPENRESULT_TAG_OK:
            z_t74_free((z_t74_t*)u->data);
            free(u->data);
            break;
        case Z_OPENRESULT_TAG_ERR:
            z_t1276_destroy((z_t1276_t*)u->data);
            free(u->data);
            break;
        default: break;
    }
}

